<script setup>
import {ref,onMounted} from 'vue';import {api,jsonBody} from '../api';import {hasPermission as h,auth} from '../auth';import RankingMonthlyBoard from './RankingMonthlyBoard.vue';import RankingInbox from './RankingInbox.vue';
const drill=ref(null);async function loadDrill(){try{drill.value=await api('/rankings/admin/recovery-drill');}catch(e){error.value=e.message;}}
const emit=defineEmits(['navigate']);const error=ref(''),busy=ref(false),alerts=ref(null),rules=ref([]),dates=ref([]),rewardId=ref('');const rule=ref({lowStockThreshold:3,perStudentLimit:0,startsAt:'',endsAt:'',instructions:''});const lesson=ref({campId:'',classId:'',lessonId:'',endedAt:''});
const local=v=>v?new Date(new Date(v).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';const iso=v=>v?new Date(v).toISOString():null;
function selectRule(r){rewardId.value=r.reward_id;rule.value={lowStockThreshold:r.low_stock_threshold,perStudentLimit:r.per_student_limit,startsAt:local(r.starts_at),endsAt:local(r.ends_at),instructions:r.instructions};}
function selectLesson(d){lesson.value={campId:d.camp_id,classId:d.class_id,lessonId:d.lesson_id,endedAt:local(d.ended_at)};}
async function load(){try{if(auth.user?.admin)await loadDrill();if(h('rankings.alerts.read'))alerts.value=await api('/rankings/admin/alerts');if(h('rankings.reward_rules.read'))rules.value=await api('/rankings/admin/reward-rules');if(h('rankings.monthly.read'))dates.value=await api('/rankings/admin/lesson-dates');}catch(e){error.value=e.message;}}
async function save(path,body){if(busy.value)return;busy.value=true;error.value='';try{await api('/rankings/admin/'+path,{method:'PUT',body:jsonBody(body)});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="engagement"><p v-if="error" class="notice notice-error" role="alert">{{error}}</p><section v-if="alerts" class="panel"><h2>待办与预警</h2><button class="button button-quiet" @click="load">刷新待办</button><div class="summary"><button @click="emit('navigate','aftercare')">待取消审批 {{alerts.pendingCancellations}}</button><button @click="emit('navigate','aftercare')">待找回处理 {{alerts.pendingRecoveries}}</button><button @click="emit('navigate','operations')">对账异常 {{alerts.reconciliation.length}}</button></div><p v-for="r in alerts.lowStock" :key="r.id">库存预警：{{r.reward_name}} · 剩余 {{r.stock}} 件（阈值 {{r.threshold}}）</p></section><RankingMonthlyBoard v-if="h('rankings.monthly.read')"/>
<section v-if="h('rankings.lesson_dates.edit')||h('rankings.monthly.read')" class="panel"><h2>课程实际日期</h2><p>只填写可核实的真实上课日期；不以导入时间推断。修改后历史月榜会即时重新计算。</p><div class="scroll"><table><thead><tr><th>课节</th><th>实际日期</th><th>操作</th></tr></thead><tbody><tr v-for="d in dates" :key="d.camp_id+d.class_id+d.lesson_id"><td>{{d.lesson_name}}<small>{{d.camp_id}} / {{d.class_id}} / {{d.lesson_id}}</small></td><td>{{d.ended_at?new Date(d.ended_at).toLocaleString():'待补齐'}}</td><td><button v-if="h('rankings.lesson_dates.edit')" class="button button-quiet" @click="selectLesson(d)">设置日期</button></td></tr></tbody></table></div><form v-if="h('rankings.lesson_dates.edit')" class="form-grid" @submit.prevent="save('lesson-dates',{...lesson,endedAt:iso(lesson.endedAt)})"><label>营期ID<input v-model="lesson.campId" required maxlength="100"></label><label>班级ID<input v-model="lesson.classId" required maxlength="100"></label><label>课节ID<input v-model="lesson.lessonId" required maxlength="100"></label><label>实际课程日期<input v-model="lesson.endedAt" type="datetime-local" required></label><button class="button button-primary" :disabled="busy">保存实际日期</button></form></section>
<section v-if="h('rankings.reward_rules.read')||h('rankings.reward_rules.edit')" class="panel"><h2>奖品兑换规则</h2><p>限兑次数 0 表示不限；取消退款的订单不占次数。所有条件都由服务器校验。</p><div class="scroll"><table><thead><tr><th>奖品</th><th>库存阈值 / 每人限兑</th><th>发放说明</th><th>操作</th></tr></thead><tbody><tr v-for="r in rules" :key="r.reward_id"><td>{{r.reward_name}}</td><td>{{r.low_stock_threshold}} / {{r.per_student_limit||'不限'}}</td><td>{{r.instructions||'未填写'}}</td><td><button v-if="h('rankings.reward_rules.edit')" class="button button-quiet" @click="selectRule(r)">修改规则</button></td></tr></tbody></table></div><form v-if="h('rankings.reward_rules.edit')" class="form-grid" @submit.prevent="save('reward-rules/'+rewardId,{...rule,startsAt:iso(rule.startsAt),endsAt:iso(rule.endsAt)})"><label>奖品ID<input v-model="rewardId" type="number" min="1" required></label><label>低库存阈值<input v-model.number="rule.lowStockThreshold" type="number" min="0" required></label><label>每人累计限兑<input v-model.number="rule.perStudentLimit" type="number" min="0" required></label><label>兑换开始时间<input v-model="rule.startsAt" type="datetime-local"></label><label>兑换结束时间<input v-model="rule.endsAt" type="datetime-local"></label><label class="wide">发放说明<input v-model="rule.instructions" maxlength="500"></label><button class="button button-primary" :disabled="busy">保存兑换规则</button></form></section><section v-if="auth.user?.admin" class="panel"><h2>备份恢复演练报告</h2><p>仅最高管理员可查看，演练通过服务器运维脚本执行，不向普通老师开放。</p><button class="button button-quiet" @click="loadDrill">刷新演练报告</button><template v-if="drill"><p>结果：{{drill.report.status==='PASS'?'通过':drill.report.status==='FAIL'?'未通过':'尚未执行'}}</p><template v-if="drill.report.status==='PASS'"><p>备份：{{drill.report.backupName}}</p><p>恢复耗时 {{drill.report.totalSeconds}} 秒；数据库恢复 {{drill.report.databaseRestoreSeconds}} 秒</p><p>备份开始时间：{{drill.report.backupStartedAt}} · 数据关联检查通过，恢复环境定时任务关闭</p></template></template></section><RankingInbox v-if="h('rankings.messages.read')" @navigate="emit('navigate',$event)"/></section></template>
<style scoped>.engagement{display:grid;gap:20px;min-width:0}.panel{background:#fff;border:1px solid #d8e0e3;border-radius:10px;padding:20px;min-width:0}.panel h2{font-size:18px}.panel p,.panel small{color:#6b7d88;line-height:1.7}.panel small{display:block;font-size:11px}.summary{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.summary button{padding:12px;border:1px solid #cee5df;border-radius:6px;background:#eef8f5;color:#16766f;cursor:pointer}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e1e9ea;text-align:left;min-width:100px}.form-grid{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin-top:18px}.form-grid label{display:grid;gap:6px;flex:1 1 170px;font-size:13px}.form-grid input{padding:10px;border:1px solid #d8e0e3;border-radius:6px;min-width:0;max-width:100%}.form-grid .wide{flex-basis:100%}</style>
